import copy

DEFAULTS = {
    "db": {"host": "localhost", "pool_size": 5},
    "cache": {"ttl": 60, "tags": ["app"]},
    "debug": False,
}


def build_config(base, overrides):
    config = copy.deepcopy(base)       # base.copy() would share the nested dicts and lists with base
    for section, value in overrides.items():
        if isinstance(value, dict):
            config.setdefault(section, {}).update(value)
        else:
            config[section] = value
    return config
